# shellcheck shell=bash disable=SC2154  # variables come from apply-theme.sh and the earlier parts
# scripts/theme.d/07-herdr.sh: part of apply-theme.sh, sourced in order in the same shell (not run on its own)
# ==========================================
# 7. Herdr (config.toml via ~/.cache/theme/herdr.toml)
# ==========================================
cat <<EOF > "$CACHE_DIR/herdr.toml"
# Generated by apply-theme.sh (Dotfiles Color Engine)
onboarding = false

[theme]
name = "dracula"

[theme.custom]
sidebar_bg = "$BG"
active_row_bg = "$BG_ALT"
selection_bg = "$BG_VISUAL"
panel_bg = "$BG"
surface_dim = "$FG_MUTED"
text = "$FG"
accent = "$ACCENT"
mauve = "$ACCENT_SOFT"
red = "$ANSI_RED"
green = "$ANSI_GREEN"
yellow = "$ANSI_YELLOW"
EOF

